!function(){const t=document.querySelectorAll(".demo-q-btn"),e=document.getElementById("demoOutput");if(!t.length||!e)return;const n=window.DEMO_CONTEXT||"general";t.forEach(o=>o.addEventListener("click",()=>async function(o){const a=o.dataset.q;t.forEach(t=>t.classList.remove("active")),o.classList.add("active"),t.forEach(t=>t.disabled=!0),e.textContent="Thinking...";try{const t=await fetch(window.getApiUrl("/api/assistant"),{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({question:a,context:n})});if(!t.ok){const e=await t.json().catch(()=>({}));throw new Error(e.error||"Request failed")}const o=await t.json();e.textContent=o.text||"No response received."}catch(t){e.textContent="Couldn't reach the assistant right now — please try again shortly."}finally{t.forEach(t=>t.disabled=!1)}}(o)))}();